const $=s=>document.querySelector(s),KEY='lacan.lexique.v1',LEVELS=['unseen','again','unsure','known'];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const BUILTIN_WORDS=WORDS.slice();
const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let state={records:{},customWords:[],settings:{rate:.85,voice:''}},q='',favorites=false,allAnswersVisible=false,listScroll=0,session=null,scope='all',voiceList=[],storageError=false;
function validate(x,vocabulary=WORDS){if(!x||![1,2].includes(x.version)||!x.records||typeof x.records!=='object'||Array.isArray(x.records))throw Error('形式が対応していません');const clean={};for(const [id,r] of Object.entries(x.records)){if(!vocabulary.some(w=>w.id===id)||!r||typeof r.favorite!=='boolean'||!LEVELS.includes(r.level)||!Number.isInteger(r.reviewCount)||r.reviewCount<0||!(r.lastReviewedAt===null||typeof r.lastReviewedAt==='string'&&!isNaN(Date.parse(r.lastReviewedAt))))throw Error('学習記録の内容が正しくありません');clean[id]={favorite:r.favorite,level:r.level,reviewCount:r.reviewCount,lastReviewedAt:r.lastReviewedAt};}return clean;}
try{let raw=localStorage.getItem(KEY);if(raw){let x=JSON.parse(raw);const custom=validateCustom(x.customWords||[]);const all=[...BUILTIN_WORDS,...custom.map(materialize)];const records=validate({...x,version:x.version||1},all);state.records=records;state.customWords=custom;WORDS.splice(0,WORDS.length,...all);if(x.settings&&Number.isFinite(x.settings.rate)&&x.settings.rate>=.6&&x.settings.rate<=1.2)state.settings={rate:x.settings.rate,voice:typeof x.settings.voice==='string'?x.settings.voice:''};}}catch(e){storageError=true;}

function record(id){return state.records[id]||{favorite:false,level:'unseen',reviewCount:0,lastReviewedAt:null};}
function save(){if(storageError){toast('保存済み記録を読み込めないため上書きできません。設定から原本を退避してください。');return false;}try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{toast('記録を保存できません。バックアップを書き出してください。');return false;}}
let timer;function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(timer);timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function fav(id){state.records[id]={...record(id),favorite:!record(id).favorite};save();const b=document.querySelector(`[data-fav="${id}"]`);if(b){b.textContent=record(id).favorite?'★':'☆';b.classList.toggle('starred',record(id).favorite);b.setAttribute('aria-pressed',record(id).favorite);}if(!location.hash.includes('word/')&&favorites)renderList();}
function stopSound(){if(typeof stopBulkSpeech==='function')stopBulkSpeech();if('speechSynthesis'in window)speechSynthesis.cancel();}
function sound(w){stopSound();if(!('speechSynthesis'in window)){toast('この環境は読み上げに対応していません。Safariでお試しください。');return;}speechSynthesis.cancel();let voices=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith('fr'));if(!voices.length){toast('フランス語の音声が見つかりません。iPhoneの読み上げ音声設定をご確認ください。');return;}let u=new SpeechSynthesisUtterance(w.audio.speechText);u.lang='fr-FR';u.rate=state.settings.rate;u.voice=voices.find(v=>v.voiceURI===state.settings.voice)||voices.find(v=>v.lang==='fr-FR')||voices[0];u.onerror=e=>{if(!['interrupted','canceled'].includes(e.error))toast('音声を再生できませんでした。もう一度お試しください。');};speechSynthesis.speak(u);}
function audioBtn(w){return `<button class="icon" data-sound="${w.id}" aria-label="${esc(w.termFr)}の発音を聞く"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 9v6h4l5 4V5L7 9H3Z" fill="currentColor"/><path d="M16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg></button>`;}
function favBtn(w){return `<button class="icon ${record(w.id).favorite?'starred':''}" data-fav="${w.id}" aria-label="${esc(w.termFr)}をお気に入りに登録・解除" aria-pressed="${record(w.id).favorite}">${record(w.id).favorite?'★':'☆'}</button>`;}
function filtered(){return courseWords().filter(w=>matchesCoreFilters(w)&&(!favorites||record(w.id).favorite)&&norm([w.termFr,w.termJa,...w.aliases].join(' ')).includes(norm(q)));}
function exampleHtml(w){const example=WORD_EXAMPLES[w.id];return example?`<div class="word-example"><span class="example-label">例文</span><p class="example-fr" lang="fr">${esc(example.fr)}</p><p class="example-ja" lang="ja">${esc(example.ja)}</p></div>`:'';}
function meaningHtml(w){return (w.senses||[{pos:'',meaning:w.termJa}]).map(s=>`<span class="meaning-row">${s.pos?`<span class="pos-label">${esc(s.pos)}</span>`:''}<span class="meaning-text">${esc(s.meaning)}</span></span>`).join('')+exampleHtml(w);}
function renderList(){let ws=filtered();$('#results').innerHTML=ws.map(w=>`<article class="word"><div class="word-original"><span class="number">${w.custom?'＋':wordNumber(w)}</span><div class="word-original-line"><a class="word-link" href="#word/${w.id}"><span class="fr" lang="fr">${esc(w.termFr)}</span></a>${audioBtn(w)}</div></div><div class="word-translation"><div id="list-${w.id}" class="ja answer-text" ${allAnswersVisible?'':'hidden'}>${meaningHtml(w)}</div><button class="answer-toggle" data-answer="list-${w.id}" aria-expanded="${allAnswersVisible}" aria-controls="list-${w.id}">${allAnswersVisible?'答えを隠す':'答えを見る'}</button></div></article>`).join('')+(!ws.length?'<div class="empty">該当する単語がありません。<br>検索語や絞り込みを変えてみてください。</div>':'');$('#result-count').textContent=ws.length+'語';}
function dictionary(){return `<div class="all-answers-toolbar"><button id="all-answers" class="primary" aria-pressed="${allAnswersVisible}" aria-controls="results">${allAnswersVisible?'すべての日本語の答えを隠す':'すべての日本語の答えを見る'}</button></div><input id="search" class="search" type="search" placeholder="原語・日本語で探す" aria-label="単語を検索" value="${esc(q)}"><div class="dictionary-toolbar"><h1>単語一覧 <span id="result-count"></span></h1></div><div class="list-options"><button class="chip ${favorites?'selected':''}" id="only-fav" aria-pressed="${favorites}">☆ お気に入り</button></div><div id="results"></div><footer>収録100語：ラカン関連20語 ＋ フーコー読解80語${state.customWords.length?` ／ 以前の登録単語 ${state.customWords.length}語`:""}<br>原語をタップすると詳しい説明・お気に入りを表示します。<br>説明は読解用草稿です。各著作の文脈・原文とあわせてご利用ください。</footer>`;}
function detail(id){let w=WORDS.find(w=>w.id===id);if(!w)return '<h1>単語が見つかりません</h1><a href="#dictionary">辞典へ戻る</a>';return `<div class="detail-top"><a class="back" href="#dictionary">← 辞典へ</a><span class="eyebrow">${w.custom?"MY WORD":wordNumber(w)} / ${WORDS.length}</span></div><p class="sub">フランス語から意味を思い出してみましょう</p><h1 class="term-heading"><span class="fr" lang="fr">${esc(w.termFr)}</span>${audioBtn(w)}</h1><div class="detail-top"><button class="primary" data-answer="detail-answer" aria-expanded="false" aria-controls="detail-answer">答えを見る</button>${favBtn(w)}</div><section id="detail-answer" hidden><div class="meaning-block">${meaningHtml(w)}</div><p class="notes">${esc(w.category)} · 品詞は表示している訳語での用法です。</p>${w.aliases.length?`<p class="notes">別表記：${w.aliases.map(esc).join(' / ')}</p>`:''}<p class="definition">${esc(w.shortDefinition)}</p>${w.pitfalls?`<div class="panel"><h3>混同しやすいこと</h3>${esc(w.pitfalls)}</div>`:""}${w.relatedIds.length?"<h3>つながる言葉</h3>":""}<div class="links">${w.relatedIds.map(id=>{let a=WORDS.find(x=>x.id===id);return `<a href="#word/${id}">${esc(a.termFr)}</a>`;}).join('')}</div>${w.explanation?`<details open><summary>もう少し詳しく</summary><p class="preserve-lines">${esc(w.explanation)}</p></details>`:""}${w.sourceNote||w.custom?`<details><summary>出典・メモ</summary><p class="preserve-lines">${esc(w.sourceNote||"未記入")}</p><p class="notes">${esc(w.reviewStatus)}</p></details>`:`<details><summary>出典・編集状況</summary><p class="notes">${esc(w.reviewStatus)}。短い説明は編集による要約で、ラカン本文からの引用ではありません。</p><a href="https://plato.stanford.edu/entries/lacan/" target="_blank" rel="noopener">Stanford Encyclopedia of Philosophy — Jacques Lacan</a><p class="notes">参照箇所：${w.sourceSection==='Seminar XI'?'第XI巻の関連議論（本文照合予定）':w.sourceSection}。版・講義日・ページは未登録です。</p>${w.sourceSection==='Seminar XI'?'<a href="https://www.lacan.com/seminars2.htm" target="_blank" rel="noopener">セミネール第XI巻の紹介</a>':''}</details>`}</section><footer>▷ 端末のフランス語合成音声 · 発音は未校閲</footer>`;}
function review(){if(!session)return `<div class="eyebrow">RÉVISION</div><h1>言葉を、もう一度。</h1><p class="sub">思い出してから、答えをめくる。<br>1回10語の小さな復習です。</p><div class="panel"><h3>学習の記録</h3><p>覚えた ${courseWords().filter(w=>record(w.id).level==='known').length} / ${courseWords().length}語　 ·　 お気に入り ${courseWords().filter(w=>record(w.id).favorite).length}語</p></div><label for="scope">出題する単語</label><select id="scope"><option value="all">すべて（未学習・苦手を優先）</option><option value="favorite">お気に入り</option><option value="weak">まだ・曖昧</option></select><p><button class="primary" id="start">復習をはじめる →</button></p>`;if(session.index>=session.words.length)return `<div class="eyebrow">BIEN JOUÉ</div><h1>ひと区切り。</h1><p>${session.words.length}語を復習しました。</p><div class="panel">まだ ${session.counts.again}語　·　曖昧 ${session.counts.unsure}語　·　覚えた ${session.counts.known}語</div><button class="primary" id="finish">復習メニューに戻る</button>`;let w=session.words[session.index];return `<div class="detail-top"><span class="eyebrow">RÉVISION</span><button id="finish">終了</button></div><p class="notes">${session.index+1} / ${session.words.length}</p><div class="progress"><div style="width:${session.index/session.words.length*100}%"></div></div><div class="card"><div class="fr">${esc(w.termFr)}</div>${audioBtn(w)}${session.revealed?`<div class="answer"><div class="meaning-block">${meaningHtml(w)}</div><p>${esc(w.shortDefinition)}</p><a href="#word/${w.id}">詳しく読む →</a></div>`:'<p class="notes">この言葉の意味は？</p><button id="reveal" class="primary">答えを見る</button>'}</div>${session.revealed?'<div class="actions"><button data-grade="again">まだ</button><button data-grade="unsure">曖昧</button><button data-grade="known" class="primary">覚えた</button></div>':''}`;}
function settings(){return `<div class="eyebrow">PRÉFÉRENCES</div><h1>あなたの読み方で。</h1><section class="settings-section"><h2>フランス語の音声</h2><p class="notes">すべての単語を端末のフランス語合成音声で読み上げます。声は端末によって異なります。このサイトからGoogleの音声生成APIを呼ぶことはありません。</p><label for="voice">声（端末音声）</label><select id="voice"></select><label for="rate">再生・読み上げ速度 <span id="rate-value">${state.settings.rate.toFixed(2)}</span></label><input id="rate" type="range" min="0.6" max="1.2" step="0.05" value="${state.settings.rate}"><button data-sound="lac-012">▷ désir を試聴</button> <button id="refresh-voices">音声一覧を更新</button><p class="notes">iPhoneで高品質なフランス語音声を追加した場合は、一覧を更新して試聴してください。Safariで選べる声は端末・OSによって異なり、すべての声が表示されるとは限りません。</p></section><section class="settings-section"><h2>学習記録のバックアップ</h2><p class="notes">30日学習・苦手語・お気に入り・学習記録はこのブラウザに保存されます。以前の登録単語があれば、それもバックアップに含まれます。端末間の自動同期はありません。ブラウザのデータ削除に備えて、ときどき書き出してください。</p><div class="actions"><button id="export">書き出す ↓</button><button id="import">読み込む ↑</button></div><input hidden id="file" type="file" accept="application/json,.json"></section><section class="settings-section"><h2>ホーム画面に追加</h2><p class="notes">iPhoneのSafariで開き、共有メニューから「ホーム画面に追加」を選びます。初期版はオンラインでご利用ください。</p></section><footer>LEXIQUE v13 · 基礎1000語 ＋ 思想・哲学100語<br>本人専用 · 訳語・解説は読解用草稿</footer>`;}
function fillVoices(){if(!$('#voice'))return;voiceList='speechSynthesis'in window?speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith('fr')):[];$('#voice').innerHTML='<option value="">フランス語の標準音声</option>'+voiceList.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${esc(v.lang)})</option>`).join('');$('#voice').value=state.settings.voice;}
function render(){stopSound();let route=(location.hash||'#dictionary').slice(1);if(route==='add'||route.startsWith('edit/'))route='dictionary';let tab=route.startsWith('word/')?'dictionary':['learn','study'].includes(route)?'study':route==='weak'?'review':route;document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.tab===tab);if(a.dataset.tab===tab)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#app').innerHTML=route.startsWith('word/')?detail(route.slice(5)):route==='study'?studyHome():route==='learn'?studyCard():route==='weak'?weakCard():route==='review'?reviewScreen():route==='settings'?settings():dictionary();if($('#results')){renderList();$('#search').addEventListener('input',e=>{q=e.target.value;renderList();});}if($('#scope'))$('#scope').value=scope;if($('#voice')){fillVoices();$('#voice').onchange=e=>{state.settings.voice=e.target.value;save();};$('#rate').oninput=e=>{state.settings.rate=Number(e.target.value);$('#rate-value').textContent=state.settings.rate.toFixed(2);save();};$('#file').onchange=importFile;}bindV13();window.scrollTo(0,route==='dictionary'?listScroll:0);}
async function importFile(e){let f=e.target.files[0];if(!f)return;try{if(f.size>25000000)throw Error('ファイルが大きすぎます（25MBまで）');let x=JSON.parse(await f.text());const custom=x.version===2?validateCustom(x.customWords):state.customWords;const all=[...BUILTIN_WORDS,...custom.map(materialize)];const records=validate(x,all);if(!confirm(`${custom.length}語の追加単語と${Object.keys(records).length}語の学習記録を復元します。${x.version===1?'旧形式のため現在の追加単語は保持します。':'現在の追加単語を置き換えます。'}学習記録は置き換わります。よろしいですか？`))return;const next={...state,customWords:custom,records};if(!persistCandidate(next))return;WORDS.splice(0,WORDS.length,...all);session=null;toast('単語と学習記録を復元しました');render();}catch(err){toast('読み込めません：'+err.message);}finally{if($('#file'))$('#file').value='';}}

document.addEventListener('click',e=>{let b=e.target.closest('button');if(e.target.closest('.word-link'))listScroll=window.scrollY;if(!b)return;if(b.id==='all-answers'){allAnswersVisible=!allAnswersVisible;b.setAttribute('aria-pressed',String(allAnswersVisible));b.textContent=allAnswersVisible?'すべての日本語の答えを隠す':'すべての日本語の答えを見る';renderList();return;}if(b.dataset.answer){let answer=document.getElementById(b.dataset.answer);answer.hidden=!answer.hidden;b.setAttribute('aria-expanded',String(!answer.hidden));b.textContent=answer.hidden?'答えを見る':'答えを隠す';return;}if(b.dataset.sound){sound(WORDS.find(w=>w.id===b.dataset.sound));return;}if(b.dataset.fav){fav(b.dataset.fav);return;}if(b.id==='only-fav'){favorites=!favorites;listScroll=0;render();}if(b.id==='start'){scope=$('#scope').value;let ws=courseWords().filter(w=>scope==='all'||scope==='favorite'&&record(w.id).favorite||scope==='weak'&&['again','unsure'].includes(record(w.id).level));if(!ws.length){toast('この範囲にはまだ単語がありません');return;}ws.sort((a,b)=>{let order={again:0,unsure:1,unseen:2,known:3};return order[record(a.id).level]-order[record(b.id).level]||(record(a.id).lastReviewedAt||'').localeCompare(record(b.id).lastReviewedAt||'');});session={words:ws.slice(0,10),index:0,revealed:false,counts:{again:0,unsure:0,known:0}};render();}if(b.id==='reveal'){session.revealed=true;render();}if(b.dataset.grade&&session&&session.revealed){let w=session.words[session.index],r=record(w.id);state.records[w.id]={...r,level:b.dataset.grade,reviewCount:r.reviewCount+1,lastReviewedAt:new Date().toISOString()};save();session.counts[b.dataset.grade]++;session.index++;session.revealed=false;render();}if(b.id==='finish'){session=null;render();}if(b.id==='export'){let data={version:2,exportedAt:new Date().toISOString(),customWords:state.customWords,records:state.records};let url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));let a=document.createElement('a');a.href=url;a.download='lacan-progress-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}if(b.id==='import')$('#file').click();if(b.id==='refresh-voices'){fillVoices();toast('利用できるフランス語音声：'+voiceList.length+'種類');}});
if('speechSynthesis'in window)speechSynthesis.addEventListener('voiceschanged',fillVoices);if(storageError)toast('保存済み記録を読み込めませんでした。バックアップがあれば復元してください。');

function persistCandidate(next){try{localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch{toast('保存できませんでした。空き容量を確認して再度お試しください。');return false;}}
